package vn.teaching.preparation;
import com.google.gson.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import vn.teaching.service.PlanningService;
import vn.teaching.exam.*;
import vn.teaching.integrations.*;
import java.nio.file.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class PreparationExportTest {
 @TempDir Path dir;
 JsonObject doc(){return JsonParser.parseString("{\"title\":\"Public lesson\",\"sections\":[{\"title\":\"Topic\",\"body\":\"Student content\",\"teacherNotes\":\"PRIVATE_ANSWER\"}],\"scenes\":[],\"exportTemplate\":{\"school\":\"Test school\",\"faculty\":\"Science faculty\",\"name\":\"Custom export\",\"fields\":[{\"label\":\"Goal\",\"source\":\"custom\",\"value\":\"Public goal\"},{\"label\":\"Notes\",\"source\":\"teacherNotes\"}]}}").getAsJsonObject();}
 String pdf(JsonObject d,String audience)throws Exception{JsonObject result=PreparationPdf.generate(d,dir,audience);var a=result.getAsJsonArray("artifacts").get(0).getAsJsonObject();assertEquals(audience,a.get("audience").getAsString());try(var loaded=org.apache.pdfbox.Loader.loadPDF(Path.of(a.get("path").getAsString()).toFile())){return new org.apache.pdfbox.text.PDFTextStripper().getText(loaded);}}
 @Test void mappedTemplatePreviewUsesAudienceBoundary()throws Exception{String student=pdf(doc(),"student"),teacher=pdf(doc(),"teacher");assertTrue(student.contains("Test school"));assertTrue(student.contains("Science faculty"));assertTrue(student.contains("Goal: Public goal"));assertFalse(student.contains("PRIVATE_ANSWER"));assertFalse(student.contains("Notes:"));assertTrue(teacher.contains("PRIVATE_ANSWER"));assertTrue(teacher.contains("BẢN GIÁO VIÊN"));}
 @Test void rejectsUnknownMappingsAndAudience(){JsonObject d=doc();d.getAsJsonObject("exportTemplate").getAsJsonArray("fields").get(0).getAsJsonObject().addProperty("source","document.secret");assertThrows(ExamException.class,()->PreparationPdf.generate(d,dir));assertThrows(ExamException.class,()->PreparationPdf.generate(doc(),dir,"unknown"));}
 @Test void longUnbrokenWordsPaginateWithoutGlyphOverflow()throws Exception{JsonObject d=doc();d.getAsJsonObject("exportTemplate").add("fields",new JsonArray());d.getAsJsonArray("sections").get(0).getAsJsonObject().addProperty("body","https://example.test/"+"x".repeat(16000));String text=pdf(d,"student");assertTrue(text.contains("https://example.test/"));assertTrue(text.contains("xxxxx"));}
 @Test void ownedImageResolverFiltersPrivateImages()throws Exception{JsonObject d=doc();JsonObject bank=new JsonObject();JsonArray images=new JsonArray();for(boolean secret:new boolean[]{false,true}){JsonObject image=new JsonObject();image.addProperty("private",secret);image.addProperty("imageAssetId",secret?"private":"public");images.add(image);}bank.add("images",images);d.getAsJsonArray("sections").get(0).getAsJsonObject().add("questionBank",bank);Path png=dir.resolve("q.png");javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(20,20,java.awt.image.BufferedImage.TYPE_INT_RGB),"png",png.toFile());java.util.List<String> resolved=new java.util.ArrayList<>();PreparationPdf.generate(d,dir,"student",id->{resolved.add(id);return png;});assertEquals(java.util.List.of("public"),resolved);resolved.clear();PreparationPdf.generate(d,dir,"teacher",id->{resolved.add(id);return png;});assertEquals(java.util.List.of("public","private"),resolved);}
 @Test void mappedFieldsControlOrderAndDoNotDuplicateBody()throws Exception{JsonObject d=doc();JsonArray fields=d.getAsJsonObject("exportTemplate").getAsJsonArray("fields");fields.remove(1);JsonObject body=new JsonObject();body.addProperty("label","Mapped body");body.addProperty("source","section.body");fields.add(body);String text=pdf(d,"student");assertEquals(1,text.split("Student content",-1).length-1);assertTrue(text.indexOf("Goal: Public goal")<text.indexOf("Mapped body:"));assertTrue(pdf(d,"teacher").contains("PRIVATE_ANSWER"));}
 @Test void malformedTemplateFailsExplicitly(){for(String raw:java.util.List.of("42","{\"fields\":42}","{\"school\":true}","{\"fields\":[{\"source\":\"custom\",\"value\":42}]}")){JsonObject d=doc();d.add("exportTemplate",JsonParser.parseString(raw));assertThrows(ExamException.class,()->PreparationExportTemplate.blocks(d,true));}}
 @Test void privateCustomMappingIsTeacherOnlyAndFlagMustBeBoolean()throws Exception {JsonObject d=doc();JsonObject field=new JsonObject();field.addProperty("label","Private field");field.addProperty("source","custom");field.addProperty("value","SECRET_CUSTOM_SENTINEL");field.addProperty("teacherOnly",true);d.getAsJsonObject("exportTemplate").getAsJsonArray("fields").add(field);assertFalse(pdf(d,"student").contains("SECRET_CUSTOM_SENTINEL"));assertTrue(pdf(d,"teacher").contains("SECRET_CUSTOM_SENTINEL"));field.addProperty("teacherOnly","true");assertThrows(ExamException.class,()->PreparationPdf.generate(d,dir));}
 @Test void studentAssetGuardRejectsPrivateMetadataAndLegacyKind(){for(String mode:java.util.List.of("kind","audience","private")){JsonObject a=new JsonObject();if(mode.equals("private"))a.addProperty(mode,true);else a.addProperty(mode,mode.equals("kind")?"question_private":"teacher");assertThrows(ExamException.class,()->PreparationJobs.requireStudentAsset(a));}}
 @Test void privateArtifactsCannotPublishEvenWithExternalConfirmation()throws Exception{PlanningService planning=new PlanningService(dir,new Gson());String plan=planning.saveOrUpdatePlanning(null,"Lesson","General",null).getId();PreparationStore store=new PreparationStore(dir,new Gson(),planning);Path file=dir.resolve("teacher.pdf");Files.writeString(file,"private");JsonObject asset=store.register(plan,"a",file,"teacher.pdf","application/pdf","pdf",0,"teacher");assertTrue(asset.get("private").getAsBoolean());JsonObject request=JsonParser.parseString("{\"revision\":0,\"requestId\":\"request-1\",\"courseId\":\"course-1\",\"title\":\"Lesson\",\"externalFilesConfirmed\":true}").getAsJsonObject();JsonArray ids=new JsonArray();ids.add(asset.get("id"));request.add("artifactIds",ids);var gateway=mock(GoogleGateway.class);var publishing=new PreparationPublishing(store,mock(ExamRepository.class),mock(GoogleConnectionService.class),gateway,mock(PreparationDrive.class));assertThrows(ExamException.class,()->publishing.publish(plan,new ExamModels.Account("a","t@example.test","T","TEACHER"),"t@example.test",request));verifyNoInteractions(gateway);}
}
